import { z } from "zod";

/**
 * M11 notification variables. Every channel is optional, and a channel is either fully set or
 * not at all: a half-set channel is refused at boot, so it can never send with a missing key.
 * Keys are generated by the owner (VAPID: `pnpm --filter @aroma/web notify:vapid`; Telegram:
 * @BotFather) and never committed.
 */
const b64url = (bytes: number) =>
  z
    .string()
    .regex(/^[A-Za-z0-9_-]+$/, "must be base64url")
    .refine((value) => Buffer.from(value, "base64url").length === bytes, {
      message: `must decode to ${bytes} bytes`,
    });

export const notifyShape = {
  /** `off` pauses delivery and new opt-ins (rollback switch). Default on. */
  AROMA_NOTIFICATIONS: z.enum(["on", "off"]).default("on"),
  /** Bearer secret for POST /api/v1/notifications/deliver (QStash or cron). */
  AROMA_NOTIFY_WORKER_SECRET: z
    .string()
    .min(32, "must be at least 32 characters")
    .optional(),
  /** Web push (RFC 8292): the P-256 public key (65 bytes) and private key (32 bytes), base64url. */
  VAPID_PUBLIC_KEY: b64url(65).optional(),
  VAPID_PRIVATE_KEY: b64url(32).optional(),
  /** The contact the push services see: `mailto:` or an https URL of the operator. */
  VAPID_SUBJECT: z
    .string()
    .regex(/^(mailto:\S+@\S+|https:\/\/\S+)$/, "must be mailto: or https://")
    .optional(),
  /** Telegram bot (@BotFather token), its username, and the webhook's secret token. */
  TELEGRAM_BOT_TOKEN: z
    .string()
    .regex(/^\d{5,16}:[A-Za-z0-9_-]{30,64}$/, "must be a bot token")
    .optional(),
  TELEGRAM_BOT_USERNAME: z
    .string()
    .regex(/^[A-Za-z0-9_]{5,32}$/, "must be a bot username without @")
    .optional(),
  TELEGRAM_WEBHOOK_SECRET: z
    .string()
    .regex(/^[A-Za-z0-9_-]{32,256}$/, "must be 32-256 of A-Z a-z 0-9 _ -")
    .optional(),
  /** E2E only (test switches): deliver every channel to this loopback sink instead. */
  AROMA_V1_TEST_NOTIFY_SINK_URL: z
    .url({ message: "must be a URL" })
    .refine(
      (v) => /^http:\/\/(127\.0\.0\.1|localhost)(:\d+)?(\/\S*)?$/.test(v),
      {
        message: "must be a loopback http URL",
      },
    )
    .optional(),
};

export const NOTIFY_CHANNEL_VARIABLES = {
  push: ["VAPID_PUBLIC_KEY", "VAPID_PRIVATE_KEY", "VAPID_SUBJECT"],
  telegram: [
    "TELEGRAM_BOT_TOKEN",
    "TELEGRAM_BOT_USERNAME",
    "TELEGRAM_WEBHOOK_SECRET",
  ],
} as const;

type Ctx = {
  addIssue(issue: { code: "custom"; path: string[]; message: string }): void;
};

/** A channel is all-or-nothing; a production deployment with a channel needs the worker secret. */
export function notifyRules(
  env: Record<string, string | boolean | undefined>,
  ctx: Ctx,
): void {
  let anyChannel = false;
  for (const variables of Object.values(NOTIFY_CHANNEL_VARIABLES)) {
    const set = variables.filter((key) => env[key] !== undefined);
    if (set.length > 0) anyChannel = true;
    if (set.length > 0 && set.length < variables.length)
      for (const key of variables.filter((k) => env[k] === undefined))
        ctx.addIssue({
          code: "custom",
          path: [key],
          message: `is required when ${set.join(", ")} is set (a channel is all or nothing)`,
        });
  }
  if (
    anyChannel &&
    env.VERCEL_ENV === "production" &&
    env.AROMA_NOTIFY_WORKER_SECRET === undefined
  )
    ctx.addIssue({
      code: "custom",
      path: ["AROMA_NOTIFY_WORKER_SECRET"],
      message: "is required in production when a notification channel is set",
    });
  if (env.VERCEL_ENV === "production" && env.AROMA_V1_TEST_NOTIFY_SINK_URL)
    ctx.addIssue({
      code: "custom",
      path: ["AROMA_V1_TEST_NOTIFY_SINK_URL"],
      message: "must not be set in a production deployment",
    });
}
